INSERT INTO public.roles (id, name, description, is_system, sort_order, extra) VALUES
  ('R01', 'Administrator', 'Full access to every module, approves all documents, manages staff and roles.', true, 0, NULL),
  ('R02', 'Sales executive', 'Handles leads and customers, prepares quotations for approval.', NULL, 1, NULL),
  ('R03', 'Sales manager', 'Runs the sales team and approves quotations.', NULL, 2, NULL),
  ('R04', 'Production supervisor', 'Plans and runs work orders, raises indents and material requisitions, approves requisitions.', NULL, 3, NULL),
  ('R05', 'Stores & purchase', 'Store in-charge: runs the stores desk, inventory and procurement planning, responds to shop-floor requests, raises indents and POs, records GRNs.', NULL, 4, NULL),
  ('R06', 'Service engineer', 'Installation, commissioning, service tickets and AMC.', NULL, 5, NULL),
  ('R07', 'Dispatch & logistics', 'Prepares documents and dispatches finished orders.', NULL, 6, NULL),
  ('R08', 'Quality inspector', 'Inspects incoming material and approves or rejects GRNs.', NULL, 7, NULL),
  ('R09', 'Security', 'Records vehicles and material at the gate.', NULL, 8, NULL),
  ('R10', 'Accounts', 'Records advances and customer payments, books vendor bills and pays vendors, maintains GST details.', NULL, 9, NULL)
